cat > tests/list-order.test.ts <<'EOF'
import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { openDatabase } from "../src/db.ts";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
}

async function createTask(server: Running, title: string): Promise<void> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  return ((await response.json()) as { tasks: Task[] }).tasks;
}

function seed(path: string, rows: [title: string, createdAt: string][]): void {
  const db = openDatabase(path);
  for (const [title, createdAt] of rows) {
    db.all(
      "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
      title,
      createdAt,
      createdAt,
    );
  }
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added in the order A, B, C", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: the list reads C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        await createTask(server, title);
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      assert.deepEqual(
        (await listTasks(server)).map((t) => t.title),
        ["C", "B", "A"],
      );
    });
  });

  describe("AC-2: tasks created within the same instant", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      const same = "2026-01-01T00:00:00.000Z";
      seed(dbPath, [
        ["first saved", same],
        ["second saved", same],
        ["third saved", same],
        ["older but saved last", "2025-12-31T23:59:59.000Z"],
      ]);
      server = await startServer(dbPath);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: the one saved last is listed first, every time", async () => {
      for (let i = 0; i < 5; i++) {
        assert.deepEqual(
          (await listTasks(server)).map((t) => t.title),
          ["third saved", "second saved", "first saved", "older but saved last"],
        );
      }
    });

    it("AC-2: creation time outranks save order", async () => {
      const tasks = await listTasks(server);
      assert.equal(tasks.at(-1)?.title, "older but saved last");
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: the API answers 200 with no tasks", async () => {
      assert.deepEqual(await listTasks(server), []);
    });

    it("AC-3: the page has an empty-state element that starts hidden", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']empty-state["'])(?=[^>]*\bhidden\b)[^>]*>/);
    });

    it("AC-3: the page script toggles the empty state from the task count", () => {
      assert.match(script, /empty-state/);
      assert.match(script, /tasks\.length/);
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      const base = Date.parse("2026-01-01T00:00:00.000Z");
      seed(
        dbPath,
        Array.from({ length: 1000 }, (_, i) => [
          `Task number ${i} with a title of ordinary length for a to-do list`,
          new Date(base + i * 1000).toISOString(),
        ]),
      );
      server = await startServer(dbPath);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: p95 latency is under 100 ms over 20 sequential requests and the body is under 400000 bytes", async () => {
      const timings: number[] = [];
      let size = 0;
      for (let i = 0; i < 20; i++) {
        const start = performance.now();
        const response = await fetch(`${server.baseUrl}/api/tasks`);
        const body = await response.arrayBuffer();
        timings.push(performance.now() - start);
        size = body.byteLength;
      }
      timings.sort((a, b) => a - b);
      const p95 = timings[Math.ceil(0.95 * timings.length) - 1];
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
      assert.ok(size < 400000, `body was ${size} bytes`);
      assert.equal(JSON.parse(new TextDecoder().decode(new Uint8Array(0)) || "null"), null);
    });

    it("AC-4: all 1000 tasks are listed, newest first", async () => {
      const tasks = await listTasks(server);
      assert.equal(tasks.length, 1000);
      assert.match(tasks[0].title, /^Task number 999 /);
    });
  });
});
EOF
